public Record create(Record value) {
    if (repository.existsById(value.id())) {
        throw new IllegalStateException("duplicate id");
    }
    return repository.save(value);
}

public void delete(String id) {
    if (!repository.existsById(id)) {
        throw new IllegalArgumentException("missing id");
    }
    repository.deleteById(id);
}

def append_text(path, content):
    with open(path, "a", encoding="utf-8") as target:
        target.write(content)

function saveObject(key: string, value: unknown): void {
    const serialized = JSON.stringify(value);
    localStorage.setItem(key, serialized);
}

function loadObject(key: string): unknown {
    const serialized = localStorage.getItem(key);
    return serialized === null ? null : JSON.parse(serialized);
}

def average(values):
    if not values:
        return 0.0
    return sum(values) / len(values)

def median(values):
    if not values:
        return 0.0
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2
